import{_ as e,o as a,c as r,ag as n}from"./chunks/framework.DTisvaUJ.js";const h=JSON.parse('{"title":"개인정보","description":"Mutelink가 외부로 보내고 PC에 저장하는 정보와 음성 인식·번역·사용 현황·문제 보고 내용을 설명합니다.","frontmatter":{"description":"Mutelink가 외부로 보내고 PC에 저장하는 정보와 음성 인식·번역·사용 현황·문제 보고 내용을 설명합니다.","head":[["meta",{"name":"robots","content":"index, follow, max-image-preview:large"}],["link",{"rel":"canonical","href":"https://utyujinn.github.io/Mutelink-releases/ko/about/privacy"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:site_name","content":"Mutelink"}],["meta",{"property":"og:locale","content":"ko_KR"}],["meta",{"property":"og:title","content":"개인정보 | Mutelink"}],["meta",{"property":"og:description","content":"Mutelink가 외부로 보내고 PC에 저장하는 정보와 음성 인식·번역·사용 현황·문제 보고 내용을 설명합니다."}],["meta",{"property":"og:url","content":"https://utyujinn.github.io/Mutelink-releases/ko/about/privacy"}],["meta",{"property":"og:image","content":"https://utyujinn.github.io/Mutelink-releases/images/og-image.png"}],["meta",{"property":"og:image:width","content":"1920"}],["meta",{"property":"og:image:height","content":"1080"}],["meta",{"property":"og:image:alt","content":"Mutelink"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"개인정보 | Mutelink"}],["meta",{"name":"twitter:description","content":"Mutelink가 외부로 보내고 PC에 저장하는 정보와 음성 인식·번역·사용 현황·문제 보고 내용을 설명합니다."}],["meta",{"name":"twitter:image","content":"https://utyujinn.github.io/Mutelink-releases/images/og-image.png"}],["meta",{"name":"twitter:image:alt","content":"Mutelink"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://utyujinn.github.io/Mutelink-releases/about/privacy"}],["link",{"rel":"alternate","hreflang":"en","href":"https://utyujinn.github.io/Mutelink-releases/en/about/privacy"}],["link",{"rel":"alternate","hreflang":"zh-Hans","href":"https://utyujinn.github.io/Mutelink-releases/zh/about/privacy"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://utyujinn.github.io/Mutelink-releases/ko/about/privacy"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://utyujinn.github.io/Mutelink-releases/about/privacy"}]]},"headers":[],"relativePath":"ko/about/privacy.md","filePath":"ko/about/privacy.md"}'),o={name:"ko/about/privacy.md"};function i(l,t,s,u,d,p){return a(),r("div",null,[...t[0]||(t[0]=[n('<h1 id="プライバシー" tabindex="-1">개인정보 <a class="header-anchor" href="#プライバシー" aria-label="Permalink to &quot;개인정보 {#プライバシー}&quot;">​</a></h1><p>Mutelink가 PC 외부로 전송하는 데이터에 관한 설명입니다.</p><h2 id="外部に送られるデータ" tabindex="-1">외부로 보내는 데이터 <a class="header-anchor" href="#外部に送られるデータ" aria-label="Permalink to &quot;외부로 보내는 데이터 {#外部に送られるデータ}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>상황</th><th>전송 내용</th><th>수신처</th></tr></thead><tbody><tr><td>클라우드 음성 인식 사용</td><td>마이크 음성</td><td>Microsoft 또는 Google</td></tr><tr><td>Azure Translator 사용</td><td>번역할 글</td><td>Microsoft(본인 키)</td></tr><tr><td>들리는 음성에 Google 선택</td><td>상대의 음성</td><td>Google</td></tr><tr><td>들리는 음성을 채팅창에 표시</td><td>상대의 발언과 번역</td><td>VRChat(인스턴스 전체에 보임)</td></tr><tr><td>사용 현황 전송 허용</td><td>익명 사용 현황(아래 설명)</td><td>개발자의 Cloudflare 서버</td></tr><tr><td>문제·요청 전송</td><td>작성한 내용과 선택한 첨부(아래 설명)</td><td>개발자의 Cloudflare 서버와 Discord</td></tr><tr><td>다운로드·업데이트 확인</td><td>통신에 필요한 정보만</td><td>각 배포처</td></tr></tbody></table><p>다음 기능은 PC 안에서만 처리하며 외부로 보내지 않습니다.</p><ul><li>로컬 음성 인식(Parakeet, Haas-ja, Qwen3-ASR, Whisper turbo)</li><li>읽기(VOICEVOX, Irodori-TTS, Qwen3-TTS)</li><li>로컬 번역(PLaMo, TranslateGemma)</li><li>VR 키보드의 가나·한자 변환과 병음 변환</li></ul><p>들리는 음성을 로컬에서 인식하면 상대의 음성은 PC 밖으로 나가지 않으며 인식 직후 버리고 저장하지 않습니다. Google을 선택하면 상대의 음성이 Google로 전송되므로 상대에게 알리는 등 배려해 주세요.</p><p>들리는 음성과 내 채팅창의 VR 패널은 본인에게만 보입니다. 방송 프로그램이 VR 화면을 그대로 캡처하면 패널도 표시될 수 있습니다.</p><h2 id="利用状況の送信" tabindex="-1">사용 현황 전송 <a class="header-anchor" href="#利用状況の送信" aria-label="Permalink to &quot;사용 현황 전송 {#利用状況の送信}&quot;">​</a></h2><p>Mutelink 개선을 위해 <strong>본인이 허용한 경우에만</strong> 월 1회 익명 사용 현황을 보냅니다. 빠른 설정 마지막에 확인하며, 허용하지 않으면 보내지 않습니다. 설정 &gt; 기타 &gt; 앱 정보에서 변경하고 다음 전송 내용을 볼 수 있습니다.</p><ul><li><strong>전송 내용</strong>: 앱 버전, OS·CPU·GPU·메모리, 실행·VR 실행·엔진별 인식/읽기/번역·읽기/번역 오류·VR 입력 방식별 조작·채팅창 전송 횟수, 언어별 엔진·번역 우선순위·입력 방식·사용 방식·버튼 배치 변경 여부 등의 설정, 유료 기능 여부.</li><li><strong>보내지 않는 내용</strong>: 발언 내용, 인식·입력된 글, 음성, 어미 문구, 템플릿, 제외 단어, 기록, 장치 이름, API 키, 등록한 목소리 이름, 실명·연락처.</li><li><strong>수신처</strong>: 개발자가 운영하는 Cloudflare 서버. IP 주소는 저장하지 않습니다.</li><li><strong>목적</strong>: 기능 사용량과 PC 환경을 파악하여 개선 우선순위를 정하기 위함입니다.</li><li><strong>익명 ID</strong>: 앱이 만드는 무작위 번호이며 개인과 연결되지 않습니다. 설정에서 언제든 다시 만들 수 있습니다.</li></ul><h2 id="不具合・要望の送信" tabindex="-1">문제·요청 전송 <a class="header-anchor" href="#不具合・要望の送信" aria-label="Permalink to &quot;문제·요청 전송 {#不具合・要望の送信}&quot;">​</a></h2><p>설정 &gt; 기타 &gt; 앱 정보 &gt; 문제·요청 보내기로 익명 메시지를 보낼 수 있습니다. 내용을 미리 확인한 뒤 <strong>전송 버튼을 눌렀을 때만</strong> 보냅니다.</p><ul><li><strong>항상 전송</strong>: 종류(문제·요청·기타)와 작성한 글입니다. 답장을 원할 때만 연락처를 선택적으로 적습니다.</li><li><strong>선택 시에만 전송</strong>: 앱 버전과 PC 정보(OS·CPU·메모리·GPU·VRAM), 로그, 이미지 한 장. 로그와 이미지는 기본적으로 꺼져 있습니다.</li><li><strong>로그에서 제외</strong>: 발언·입력한 글이 있는 줄을 전송 시 제거하고 경로의 사용자 이름을 가립니다.</li><li><strong>이미지</strong>: 알림·이름·파일명 등 화면의 내용이 그대로 담깁니다. 개발자의 Discord로 전달되며 서버에는 저장하지 않습니다.</li><li><strong>처리</strong>: IP 주소를 저장하거나 사용 현황과 연결하지 않습니다. 이름·주소 등의 개인정보는 적지 마세요.</li></ul><h2 id="pcの中に保存されるデータ" tabindex="-1">PC에 저장하는 데이터 <a class="header-anchor" href="#pcの中に保存されるデータ" aria-label="Permalink to &quot;PC에 저장하는 데이터 {#pcの中に保存されるデータ}&quot;">​</a></h2><p>다운로드한 모델·캐릭터, 등록한 목소리의 특징(원본 녹음은 저장하지 않음), VR 배경 이미지, 라이선스 파일, 설정, 번역 글자 수 기록은 PC에 저장됩니다.</p><p>새로 설치한 경우 <code>%LOCALAPPDATA%\\com.utyujinn.mutelink</code>에 저장됩니다. 구버전부터 사용했다면 설치 폴더에 남아 있을 수 있습니다.</p><p>Azure Translator 키는 이 PC의 설정에만 저장됩니다.</p>',18)])])}const c=e(o,[["render",i]]);export{h as __pageData,c as default};
